async ({ workspace: { read, search, list } }) => {
  const [rel, h1, h2, src] = await Promise.all([
    read("docs/releasing.md", { format: "raw" }),
    search("name: \"typescript\"", { path: "src", limit: 20, contextLines: 0 }),
    search("@pit:", { path: "src", limit: 30, contextLines: 0 }),
    list("src"),
  ]);
  const fmt = (h: any) => JSON.stringify(h).slice(0, 4000);
  return { rel: rel.content, h1: fmt(h1), h2: fmt(h2), src: JSON.stringify(src).slice(0, 3000) };
}
